package packet; import core.Hex;import core.SecurityCatalog; public final class DnsRecord{private final String name;private final int type;private final int rclass;private final long ttl;private final byte[] rdata;public DnsRecord(String name,int type,int rclass,long ttl,byte[] rdata){this.name=name;this.type=type;this.rclass=rclass;this.ttl=ttl;this.rdata=rdata==null?new byte[0]:rdata;}public String name(){return name;}public int type(){return type;}public String typeName(){return SecurityCatalog.dnsTypeName(type);}public int rclass(){return rclass;}public long ttl(){return ttl;}public byte[] rdata(){return rdata;}public String rdataHex(){return Hex.encode(rdata);}}
